# The giac-openmath table, embedded: generated by test/update_openmath_table.jl.
# Source: https://github.com/JuliaGiac/giac-openmath/blob/d7311e73ec014589259d03febc9d152b4b2b5dbd/giac-openmath.toml
# Do not edit by hand: change the table there, then run the script with its commit.

const TABLE_COMMIT = "d7311e73ec014589259d03febc9d152b4b2b5dbd"
const TABLE_SHA256 = "b22905cd22ccc3dd52c2cb430a70904a57e829b7a7379505a1580d6e0485ebe3"
const TABLE_TOML = raw"""
# giac-openmath: what GIAC's expression trees mean in OpenMath Content
# Dictionaries, and back. The format is described in docs/format.md.
#
# The `giac` side is GIAC itself (the C++ library), not one binding: node
# names are those of GIAC's trees (what Giac.jl's symb_funcname returns, the
# names of GIAC's unary_function objects), read from the GIAC in giac_version. Input names
# GIAC reads as another node (log is ln, arcsin is asin) are aliases.
#
# status = "names": the node and the symbol name the same operation with
# the same arguments; that their domains, branch cuts and conventions agree
# has not been checked. A note says what is known to differ.
# What has no Content Dictionary symbol, or a false friend, is refused.

format = 1
# The GIAC the tests in test/giac ran against (GIAC_jll through Giac.jl).
# Raise it with them when GIAC_jll 2.1.0 is registered.
giac_version = "2.0.0"

[cd_source]
repository = "https://github.com/OpenMath/CDs"
commit = "cbf607561e3f90630ce7a57fe9a85f5bc0dfdd3c"
raw = "https://raw.githubusercontent.com/OpenMath/CDs/{commit}/{path}"

[cd.arith1]
path = "cd/Official/arith1.ocd"
sha256 = "8dab1c657db03b87da8ed3a139c2490df0e86076ab634c3804b757c5594f6d8a"

[cd.transc1]
path = "cd/Official/transc1.ocd"
sha256 = "75ed9e263f1256e957d56fc30648835d3d0a0c1fc375947b0a2fa1bdf71a177d"

[cd.relation1]
path = "cd/Official/relation1.ocd"
sha256 = "1c50e72514373c6d60c3f82c28936670ccb8615e8cf85b40de6ee747487842e6"

[cd.logic1]
path = "cd/Official/logic1.ocd"
sha256 = "5bd450962d9ee3f867770608ce6f823b0ad705123afb9af5d1950a39a46498cd"

[cd.nums1]
path = "cd/Official/nums1.ocd"
sha256 = "691c8ebfaad1375bdd54c6084b223a093782aacc634151bdb49ba70938ddbbe5"

[cd.rounding1]
path = "cd/Official/rounding1.ocd"
sha256 = "35280066a32b9b527b4940dcf5f726639f197b980a212badce9df4efc237ed6b"

[cd.calculus1]
path = "cd/Official/calculus1.ocd"
sha256 = "bd61e71618800e50935bd4f8503ad3d7bd7f131456854cb5d7cb49fa3df780e7"

[cd.fns1]
path = "cd/Official/fns1.ocd"
sha256 = "9d45eafcb9b527de68dee8f2a129fe8ec71667ef8490fa5e50ddb7eedd3f8c5e"

[cd.interval1]
path = "cd/Official/interval1.ocd"
sha256 = "f49fe43b4c1dc79d7972ed6fce79d02437d4920320cbd9faffdf460938717f6a"

[cd.integer1]
path = "cd/Official/integer1.ocd"
sha256 = "e8844f0415a9078293717f075fa83a06985f0ba7ddca9cd74b1d234ff79d287d"

[cd.complex1]
path = "cd/Official/complex1.ocd"
sha256 = "f3fd7eb99fcea16165a8ef44bf3adf6e14c2e6c462fbfe8cc425291d0ebaba91"

[cd.minmax1]
path = "cd/Official/minmax1.ocd"
sha256 = "d91f0dfa4caf850002a86cf76d404479d8a183eb9b1653a44dabe6d1f9e04ce9"

[cd.limit1]
path = "cd/Official/limit1.ocd"
sha256 = "b104ee1a78b9c0528344b5b375ce1790296ddeaca9d8ef5429a80e4ae4e049c6"

[cd.set1]
path = "cd/Official/set1.ocd"
sha256 = "6d4995d2e7f1f24e062f52f600f33cceabe24e3055927e668dbea6a5dd0c5ea2"

# ── Leaves: values that are not calls ─────────────────────────────────────
# Integers are OMI, identifiers OMV, GIAC fractions (FRAC) nums1.rational(p, q)
# and floats OMF (inexact: a consumer may refuse them); see docs/format.md.

[[leaf]]
giac = "pi"
om = "nums1.pi"

[[leaf]]
giac = "i"
om = "nums1.i"
note = "GIAC's i is the complex number 0+1*i (a CPLX value); any other complex value is complex1.complex_cartesian(re, im)."

[[leaf]]
giac = "euler_gamma"
om = "nums1.gamma"

[[leaf]]
giac = "e"
om = "nums1.e"
direction = "from_openmath"
note = "GIAC reads e as exp(1), which goes to OpenMath as transc1.exp(1)."

[[leaf]]
giac = "+infinity"
om = "nums1.infinity"
direction = "from_openmath"
note = "GIAC's own tree is +(infinity): see the map for it. Bare `infinity` in GIAC is unsigned, and refused."

[[leaf]]
giac = "true"
om = "logic1.true"

[[leaf]]
giac = "false"
om = "logic1.false"

# ── arith1 ─────────────────────────────────────────────────────────────────

[[map]]
giac = ["+", "#*"]
om = ["arith1.plus", "#*"]
input = "infix"
note = "GIAC writes x-y as +(x, -(y))."

[[map]]
giac = ["*", "#*"]
om = ["arith1.times", "#*"]
input = "infix"

[[map]]
giac = ["-", "#1"]
om = ["arith1.unary_minus", "#1"]
input = "prefix"

[[map]]
giac = ["-", "#1", "#2"]
om = ["arith1.minus", "#1", "#2"]
input = "infix"
direction = "from_openmath"
note = "Written a - b; GIAC reads it as +(a, -(b))."

[[map]]
giac = ["+", "infinity"]
om = "nums1.infinity"
direction = "to_openmath"
note = "GIAC's +infinity. A pattern with a name in it is tried before the general one."

[[map]]
giac = ["-", "infinity"]
om = ["arith1.unary_minus", "nums1.infinity"]
direction = "to_openmath"
note = "GIAC's -infinity."

[[map]]
giac = ["/", "#1", "#2"]
om = ["arith1.divide", "#1", "#2"]
input = "infix"
note = "An unevaluated quotient. Evaluated, GIAC writes x/y as *(x, inv(y))."

[[map]]
giac = ["inv", "#1"]
om = ["arith1.divide", 1, "#1"]
direction = "to_openmath"

[[map]]
giac = ["^", "#1", "#2"]
om = ["arith1.power", "#1", "#2"]
input = "infix"
note = "GIAC evaluates sqrt(x) to x^(1/2), with the FRAC 1/2."

[[map]]
giac = ["sqrt", "#1"]
om = ["arith1.root", "#1", 2]
note = "Unevaluated sqrt only. arith1.root leaves which root it is open; GIAC's sqrt is the principal square root."

[[map]]
giac = ["abs", "#1"]
om = ["arith1.abs", "#1"]

[[map]]
giac = ["gcd", "#*"]
om = ["arith1.gcd", "#*"]
note = "GIAC's gcd is also the gcd of polynomials; the Content Dictionary speaks of its arguments without a domain."

[[map]]
giac = ["lcm", "#*"]
om = ["arith1.lcm", "#*"]
note = "As for gcd: GIAC's lcm also takes polynomials."

[[map]]
giac = ["sum", "#1", "#2", "#3", "#4"]
om = ["arith1.sum", ["interval1.integer_interval", "#3", "#4"], ["bind", "fns1.lambda", ["#2"], "#1"]]
note = "sum(f, k, a, b): the sum of f over the integers k from a to b."

[[map]]
giac = ["product", "#1", "#2", "#3", "#4"]
om = ["arith1.product", ["interval1.integer_interval", "#3", "#4"], ["bind", "fns1.lambda", ["#2"], "#1"]]

# ── transc1 ────────────────────────────────────────────────────────────────

[[map]]
giac = ["ln", "#1"]
om = ["transc1.ln", "#1"]
aliases = ["log"]
note = "GIAC's log is the natural logarithm (a node ln), as is Julia's log; transc1.log is the logarithm to a base."

[[map]]
giac = ["logb", "#1", "#2"]
om = ["transc1.log", "#2", "#1"]
note = "logb(x, b) is log to the base b of x; transc1.log takes the base first. GIAC evaluates logb to ln(x)/ln(b)."

[[map]]
giac = ["log10", "#1"]
om = ["transc1.log", 10, "#1"]
direction = "to_openmath"
note = "From OpenMath, transc1.log(10, x) is logb(x, 10)."

[[map]]
giac = ["exp", "#1"]
om = ["transc1.exp", "#1"]

[[map]]
giac = ["sin", "#1"]
om = ["transc1.sin", "#1"]

[[map]]
giac = ["cos", "#1"]
om = ["transc1.cos", "#1"]

[[map]]
giac = ["tan", "#1"]
om = ["transc1.tan", "#1"]

[[map]]
giac = ["sec", "#1"]
om = ["transc1.sec", "#1"]
note = "GIAC evaluates sec(x) to 1/cos(x)."

[[map]]
giac = ["csc", "#1"]
om = ["transc1.csc", "#1"]
note = "GIAC evaluates csc(x) to 1/sin(x)."

[[map]]
giac = ["cot", "#1"]
om = ["transc1.cot", "#1"]
note = "GIAC evaluates cot(x) to cos(x)/sin(x)."

[[map]]
giac = ["asin", "#1"]
om = ["transc1.arcsin", "#1"]
aliases = ["arcsin"]

[[map]]
giac = ["acos", "#1"]
om = ["transc1.arccos", "#1"]
aliases = ["arccos"]

[[map]]
giac = ["atan", "#1"]
om = ["transc1.arctan", "#1"]
aliases = ["arctan"]

[[map]]
giac = ["asec", "#1"]
om = ["transc1.arcsec", "#1"]
note = "GIAC evaluates asec(x) to acos(1/x)."

[[map]]
giac = ["acsc", "#1"]
om = ["transc1.arccsc", "#1"]
note = "GIAC evaluates acsc(x) to asin(1/x)."

[[map]]
giac = ["acot", "#1"]
om = ["transc1.arccot", "#1"]
note = "GIAC evaluates acot(x) to atan(1/x), which differs from the usual arccot for x < 0."

[[map]]
giac = ["sinh", "#1"]
om = ["transc1.sinh", "#1"]

[[map]]
giac = ["cosh", "#1"]
om = ["transc1.cosh", "#1"]

[[map]]
giac = ["tanh", "#1"]
om = ["transc1.tanh", "#1"]

[[map]]
giac = ["asinh", "#1"]
om = ["transc1.arcsinh", "#1"]
aliases = ["arcsinh"]
note = "GIAC evaluates asinh(x) to ln(x + sqrt(x^2 + 1))."

[[map]]
giac = ["acosh", "#1"]
om = ["transc1.arccosh", "#1"]
aliases = ["arccosh"]
note = "GIAC evaluates acosh(x) to ln(x + sqrt(x^2 - 1))."

[[map]]
giac = ["atanh", "#1"]
om = ["transc1.arctanh", "#1"]
aliases = ["arctanh"]
note = "GIAC evaluates atanh(x) to ln((1 + x)/(1 - x))/2."

# ── relation1 ──────────────────────────────────────────────────────────────

[[map]]
giac = ["=", "#1", "#2"]
om = ["relation1.eq", "#1", "#2"]
input = "infix"
note = "GIAC's = builds an equation, kept as such."

[[map]]
giac = ["==", "#1", "#2"]
om = ["relation1.eq", "#1", "#2"]
input = "infix"
direction = "to_openmath"
note = "GIAC's == is a test, evaluated at once: x == y is false for two distinct names."

[[map]]
giac = ["<", "#1", "#2"]
om = ["relation1.lt", "#1", "#2"]
input = "infix"
note = "GIAC evaluates x < y to y > x."

[[map]]
giac = [">", "#1", "#2"]
om = ["relation1.gt", "#1", "#2"]
input = "infix"

[[map]]
giac = ["<=", "#1", "#2"]
om = ["relation1.leq", "#1", "#2"]
input = "infix"
note = "GIAC evaluates x <= y to y >= x."

[[map]]
giac = [">=", "#1", "#2"]
om = ["relation1.geq", "#1", "#2"]
input = "infix"

[[map]]
giac = ["!=", "#1", "#2"]
om = ["relation1.neq", "#1", "#2"]
input = "infix"
note = "A test, evaluated at once: x != y is true for two distinct names. GIAC prints it <>."

# ── logic1 ─────────────────────────────────────────────────────────────────

[[map]]
giac = ["and", "#*"]
om = ["logic1.and", "#*"]
input = "infix"

[[map]]
giac = ["or", "#*"]
om = ["logic1.or", "#*"]
input = "infix"

[[map]]
giac = ["not", "#1"]
om = ["logic1.not", "#1"]
note = "Write not(a): GIAC reads `not a` without parentheses as undef."

[[map]]
giac = [" xor ", "#1", "#2"]
om = ["logic1.xor", "#1", "#2"]
input = "infix"
note = "The node's name has spaces around xor. GIAC evaluates a xor b on two names to 0."

# ── rounding1 ──────────────────────────────────────────────────────────────

[[map]]
giac = ["floor", "#1"]
om = ["rounding1.floor", "#1"]

[[map]]
giac = ["ceil", "#1"]
om = ["rounding1.ceiling", "#1"]
note = "GIAC evaluates ceil(x) to -floor(-x)."

[[map]]
giac = ["round", "#1"]
om = ["rounding1.round", "#1"]
note = "GIAC evaluates round(x) to floor(x + 1/2): halves go up, which the Content Dictionary does not fix."

[[map]]
giac = ["trunc", "#1"]
om = ["rounding1.trunc", "#1"]
note = "GIAC 2.1.0 evaluates trunc(x) on a name to floor(x), wrong for x < 0; on numbers it rounds toward zero."

# ── minmax1 (over a set) ───────────────────────────────────────────────────

[[map]]
giac = ["max", "#*"]
om = ["minmax1.max", ["set1.set", "#*"]]
note = "minmax1.max takes one argument, a set."

[[map]]
giac = ["min", "#*"]
om = ["minmax1.min", ["set1.set", "#*"]]

# ── complex1 ───────────────────────────────────────────────────────────────

[[map]]
giac = ["re", "#1"]
om = ["complex1.real", "#1"]
note = "GIAC takes names as real unless declared complex: re(x) evaluates to x."

[[map]]
giac = ["im", "#1"]
om = ["complex1.imaginary", "#1"]
note = "As for re: im(x) evaluates to 0 for a name."

[[map]]
giac = ["conj", "#1"]
om = ["complex1.conjugate", "#1"]

[[map]]
giac = ["arg", "#1"]
om = ["complex1.argument", "#1"]

# ── integer1 ───────────────────────────────────────────────────────────────

[[map]]
giac = ["factorial", "#1"]
om = ["integer1.factorial", "#1"]
note = "GIAC prints factorial(n) as n!."

# ── calculus1, limit1: functions of a bound variable ───────────────────────
# OpenMath integrates and differentiates functions (fns1.lambda); GIAC,
# expressions in a variable. The derivative or antiderivative function is
# applied to the variable to give an expression again.

[[map]]
giac = ["diff", "#1", "#2"]
om = ["apply", ["calculus1.diff", ["bind", "fns1.lambda", ["#2"], "#1"]], "#2"]
note = "diff(f, x): the derivative of x -> f, at x."

[[map]]
giac = ["integrate", "#1", "#2"]
om = ["apply", ["calculus1.int", ["bind", "fns1.lambda", ["#2"], "#1"]], "#2"]
note = "integrate(f, x): an antiderivative of x -> f, at x. GIAC's int(f, x) is a node int until evaluated, then integrate."

[[map]]
giac = ["integrate", "#1", "#2", "#3", "#4"]
om = ["calculus1.defint", ["interval1.interval", "#3", "#4"], ["bind", "fns1.lambda", ["#2"], "#1"]]

[[map]]
giac = ["limit", "#1", "#2", "#3"]
om = ["limit1.limit", "#3", "limit1.both_sides", ["bind", "fns1.lambda", ["#2"], "#1"]]

[[map]]
giac = ["limit", "#1", "#2", "#3", 1]
om = ["limit1.limit", "#3", "limit1.above", ["bind", "fns1.lambda", ["#2"], "#1"]]

[[map]]
giac = ["limit", "#1", "#2", "#3", -1]
om = ["limit1.limit", "#3", "limit1.below", ["bind", "fns1.lambda", ["#2"], "#1"]]

# ── Refused: no Content Dictionary symbol, or a false friend ───────────────

[[refused]]
giac = "%"
example = "x mod 3"
om = "integer1.remainder"
reason = "GIAC's % (and x mod n) is a residue class modulo n, not a remainder: x mod 3 evaluates to (1 % 3)*x."

[[refused]]
giac = "irem"
example = "irem(a, b)"
reason = "irem(-7, 3) is 2 in GIAC; integer1.remainder gives the remainder the sign of the dividend, -1. They agree for a >= 0 and b > 0 only."

[[refused]]
giac = "iquo"
example = "iquo(a, b)"
om = "integer1.quotient"
reason = "iquo(-7, 3) is -3 in GIAC (rounding down); integer1.quotient goes with a remainder of the dividend's sign, so -2."

[[refused]]
giac = "sto"
example = "a => b"
om = "logic1.implies"
reason = "GIAC's => is an assignment (a node sto), not an implication; GIAC has no implication operator."

[[refused]]
giac = "infinity"
reason = "GIAC's bare infinity is unsigned; nums1.infinity is read as +infinity."

[[refused]]
giac = "undef"
om = "nums1.NaN"
reason = "GIAC's undef is an undefined result of any computation, not a floating-point NaN."

[[refused]]
giac = "program"
example = "x -> x^2"
reason = "GIAC's functions (x -> f) also carry local variables and statements; not mapped yet to fns1.lambda."
"""
